window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[297]={"id":"297","numero":297,"titre":"Cancers de l'enfant","objectifs":[{"id":"297-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les particularités épidémiologiques des tumeurs malignes de l’enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> cancers de l'enfant sont des <span class=\"kw-def\">maladies rares</span> : ils représentent <span class=\"kw-chiffre\">&lt; 1 %</span> de l'ensemble des cancers. Leurs types histologiques et leur fréquence sont <strong>très distincts de ceux de l'adulte</strong> — c'est le point princeps de cet objectif.</p>\n      <table >\n        <thead><tr><th>Donnée</th><th>Chiffre clé</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Incidence</span></td><td><span class=\"kw-chiffre\">2 500/an</span> en France chez <span class=\"kw-clinique\">les</span> &lt;<span class=\"kw-chiffre\"> 18 ans</span>, dont <span class=\"kw-chiffre\">1 700/an</span> chez les &lt;<span class=\"kw-chiffre\"> 15 ans</span></td></tr>\n          <tr><td>Âge</td><td><span class=\"kw-chiffre\">50 %</span> des cas surviennent avant <span class=\"kw-chiffre\">5 ans</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance masculine (<span class=\"kw-chiffre\">1,2 G / 1 F</span>)</td></tr>\n          <tr><td>Part <span class=\"kw-etio\">génétique</span></td><td><span class=\"kw-etio\">Prédisposition génétique</span> dans <span class=\"kw-chiffre\">10 %</span> des cas</td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span></td><td><span class=\"kw-alerte\">2ᵉ cause de mortalité</span> entre 1 et <span class=\"kw-chiffre\">15 ans</span> dans <span class=\"kw-clinique\">les</span> pays industrialisés (après les accidents)</td></tr>\n          <tr><td><span class=\"kw-def\">Pronostic</span></td><td>Taux de guérison <span class=\"kw-chiffre\">≈ 80 %</span> — globalement <strong>meilleur que chez l'adulte</strong> (grande chimiosensibilité, PEC en équipes spécialisées, inclusion dans des essais)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Répartition par fréquence</strong> — deux grands ensembles : <span class=\"kw-def\">hémopathies malignes</span> (<span class=\"kw-chiffre\">40 %</span>, 1ʳᵉ cause) et <span class=\"kw-def\">tumeurs solides</span> (<span class=\"kw-chiffre\">60 %</span>) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Part</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Leucémies</span> et <span class=\"kw-etio\">lymphomes</span></td><td><span class=\"kw-chiffre\">40 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Tumeurs cérébrales</span></td><td><span class=\"kw-chiffre\">25 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Neuroblastome</span></td><td><span class=\"kw-chiffre\">6 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Tumeurs des tissus mous</span> (rhabdomyosarcome)</td><td><span class=\"kw-chiffre\">6 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Néphroblastome</span></td><td><span class=\"kw-chiffre\">6 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Tumeurs osseuses</span></td><td><span class=\"kw-chiffre\">5 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Rétinoblastome</span></td><td><span class=\"kw-chiffre\">2 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Variation selon l'âge</strong> — discriminant fréquent en QCM :</p>\n      <table >\n        <thead><tr><th>Tranche d'âge</th><th>Cancers prédominants</th></tr></thead>\n        <tbody>\n          <tr><td>Avant <span class=\"kw-chiffre\">5 ans</span></td><td><span class=\"kw-etio\">Leucémies aiguës</span> (pic des LAL) ; <span class=\"kw-def\">tumeurs embryonnaires</span> du blastème spécifiques de l'enfant (<span class=\"kw-etio\">rétinoblastome</span>, <span class=\"kw-etio\">neuroblastome</span>, <span class=\"kw-etio\">néphroblastome</span>, <span class=\"kw-etio\">hépatoblastome</span>) ; tumeurs cérébrales (médulloblastome, gliome de bas <span class=\"kw-def\">grade</span>) ; rhabdomyosarcome</td></tr>\n          <tr><td>Après <span class=\"kw-chiffre\">5 ans</span></td><td>Tumeurs cérébrales (gliomes, médulloblastome) ; <span class=\"kw-def\">sarcomes osseux</span> (ostéosarcome, sarcome d'Ewing) ; sarcomes des tissus mous ; <span class=\"kw-etio\">lymphomes</span> (hodgkiniens et non hodgkiniens) ; tumeurs germinales malignes (gonadiques)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Chez l'enfant, <span class=\"kw-chiffre\">40 %</span> = hémopathies, <span class=\"kw-chiffre\">25 %</span> = tumeurs cérébrales, le reste = tumeurs embryonnaires et sarcomes. Pas de carcinomes épithéliaux fréquents avant l'adolescence (à l'inverse de l'adulte).</div>","frequence":0},{"id":"297-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principales prédispositions génétiques et autres facteurs de risque aux tumeurs malignes de l’enfant","contenu":"<p>Peu de <span class=\"kw-etio\">facteurs environnementaux</span> sont connus chez l'enfant. En revanche, une <span class=\"kw-etio\">prédisposition génétique</span> est retrouvée dans <span class=\"kw-chiffre\">10 %</span> des cas, dans le cadre de syndromes identifiés — leur reconnaissance modifie la PEC (aménagements thérapeutiques) et permet l'enquête familiale.</p>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span> environnementaux et <span class=\"kw-etio\">acquis</span></strong> :</p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Cancer associé</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Irradiation</span> à forte dose</td><td><span class=\"kw-etio\">Cancer de la thyroïde</span> (après <span class=\"kw-clinique\">irradiation</span> pour Hodgkin) ; <span class=\"kw-etio\">leucémie</span> (exposition in utero &gt; <span class=\"kw-chiffre\">10 mGy</span>). Faibles doses : risque non prouvé.</td></tr>\n          <tr><td><span class=\"kw-etio\">Virus</span></td><td><strong><span class=\"kw-etio\">VHB</span> :</strong> <span class=\"kw-etio\">hépatocarcinome</span><br><strong><span class=\"kw-etio\">VIH</span> :</strong> <span class=\"kw-etio\">lymphomes</span>, léiomyosarcome<br><strong><span class=\"kw-etio\">EBV</span> :</strong> <span class=\"kw-etio\">Burkitt</span>, <span class=\"kw-etio\">Hodgkin</span>, <span class=\"kw-clinique\">carcinome</span> indifférencié du nasopharynx</td></tr>\n          <tr><td><span class=\"kw-etio\">Iatrogène</span></td><td><strong>Alkylants, inhibiteurs des topo-isomérases II, intercalants :</strong> <span class=\"kw-etio\">leucémie</span><br><strong><span class=\"kw-ttt\">Immunosuppresseurs</span> :</strong> <span class=\"kw-etio\">lymphomes</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Chimique</span></td><td>Diéthylstilbestrol in utero : <span class=\"kw-etio\">adénocarcinome à cellules claires du vagin</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Alimentation</span></td><td>L'<span class=\"kw-clinique\">allaitement maternel</span> diminue le risque de leucémie et de tumeur du SNC (facteur protecteur)</td></tr>\n          <tr><td><span class=\"kw-etio\">Facteurs suspectés</span><br><em>(non prouvés)</em></td><td><strong>Pesticides :</strong> exposition <em>suspectée</em> dans <span class=\"kw-def\">plusieurs types de cancers</span><br>Rôle <span class=\"kw-clinique\">protecteur</span> <em>suspecté</em> des <span class=\"kw-clinique\">infections banales précoces</span> vis-à-vis des <span class=\"kw-etio\">leucémies</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Syndromes de prédisposition <span class=\"kw-etio\">génétique</span></strong> :</p>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Gène / anomalie</th><th>Cancers</th></tr></thead>\n        <tbody>\n          <tr><td>Rétinoblastome <span class=\"kw-etio\">héréditaire</span> (AD)</td><td><span class=\"kw-bio\">RB1</span></td><td>Rétinoblastome ; risque accru de <span class=\"kw-alerte\">2ᵉ cancer</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Li-Fraumeni</span> (AD)</td><td><span class=\"kw-bio\">TP53</span></td><td>Sarcomes des tissus mous et des os ; lymphomes ; tumeurs du SNC ; corticosurrénalome</td></tr>\n          <tr><td><span class=\"kw-etio\">Beckwith-Wiedemann</span></td><td><span class=\"kw-bio\">WT2</span></td><td>Néphroblastome ; hépatoblastome</td></tr>\n          <tr><td>Trisomie 21</td><td>Aberration chromosomique</td><td>Leucémies</td></tr>\n          <tr><td>Neurofibromatoses 1 et 2</td><td><span class=\"kw-bio\">NF1 / NF2</span></td><td>Tumeurs du SNC</td></tr>\n          <tr><td>Syndrome <span class=\"kw-bio\">DICER1</span></td><td><span class=\"kw-bio\">DICER1</span></td><td>Tumeurs des cordons sexuels ; pleuro-pneumoblastome</td></tr>\n          <tr><td>Maladie de Fanconi</td><td>Instabilité chromosomique</td><td>Forte prédisposition, en particulier <span class=\"kw-etio\">leucémie</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Syndrome de Turner</span></td><td>—</td><td>Gonadoblastome (bénin, mais fort risque de transformation)</td></tr>\n          <tr><td>Déficit immunitaire <span class=\"kw-etio\">héréditaire</span></td><td>—</td><td>Lymphome</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Quand évoquer un <span class=\"kw-clinique\">syndrome de prédisposition</span> ?</strong> Devant des <span class=\"kw-clinique\">cancers rares</span>, <span class=\"kw-clinique\">synchrones ou métachrones</span>, une <span class=\"kw-clinique\">histoire familiale de cancers</span>, ou l'association à des anomalies développementales (<span class=\"kw-clinique\">dysmorphie</span>, anomalies congénitales, déficience intellectuelle, anomalies cutanées ou de l'hématopoïèse).</div>","frequence":0},{"id":"297-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur cérébrale chez l’enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> tumeurs cérébrales sont la <span class=\"kw-def\">2ᵉ cause de cancer</span> de l'enfant (<span class=\"kw-chiffre\">25 %</span>). Le signe d'appel le plus fréquent est l'<span class=\"kw-alerte\">hypertension intracrânienne (HTIC)</span>.</p>\n      <p><strong>Syndrome d'<span class=\"kw-alerte\">HTIC</span></strong> — manifestations typiques :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Céphalées</span></td><td>Signe le <strong>plus précoce et le plus constant</strong> : récentes, inhabituelles, durables, s'aggravant ; surtout le <span class=\"kw-clinique\">matin au réveil</span> ou en 2ᵉ moitié de nuit ; exagérées par la <span class=\"kw-clinique\">toux</span>, l'effort, le <span class=\"kw-clinique\">décubitus</span> ; <span class=\"kw-alerte\">rebelles aux antalgiques</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Vomissements</span></td><td>Inconstants : <span class=\"kw-clinique\">en jet</span> (sans <span class=\"kw-clinique\">nausée</span>), <span class=\"kw-clinique\">matinaux</span>, peuvent soulager <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">céphalées</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres signes révélateurs</strong> (parfois sans <span class=\"kw-alerte\">HTIC</span>) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Comitialité</span>, souvent à type de crises partielles</li>\n        <li><span class=\"kw-clinique\">Déficit visuel</span></li>\n        <li>Tout <span class=\"kw-clinique\">signe de localisation neurologique</span> : atteinte motrice, des paires crâniennes, <span class=\"kw-clinique\">syndrome cérébelleux</span>…</li>\n        <li><span class=\"kw-clinique\">Déficit endocrinien d'origine centrale</span></li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Tout symptôme anormal ou persistant impose un <span class=\"kw-clinique\">examen neurologique</span> attentif ; toute anomalie clinique justifie une <span class=\"kw-imagerie\">imagerie cérébrale en urgence</span>. En cas d'<span class=\"kw-alerte\">HTIC</span>, transfert immédiat en neurochirurgie (<span class=\"kw-ttt\">DVE</span> / ventriculocisternostomie), <span class=\"kw-ttt\">corticothérapie</span> ± <span class=\"kw-ttt\">mannitol IV</span>.</div>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Terrain</span>.</strong> Une tumeur cérébrale peut s'inscrire dans un <span class=\"kw-clinique\">syndrome de prédisposition</span> : la <span class=\"kw-etio\">NF1</span> est le plus fréquent (tumeurs des voies optiques notamment).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 299 — Tumeurs intracrâniennes — <span class=\"kw-alerte\">HTIC</span> — Hydrocéphalie</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/brain-tumours-in-infancy","label":"Radiopaedia : Brain tumours in infancy"}]},{"id":"297-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur abdominale chez l’enfant","contenu":"<p><span class=\"kw-clinique\">Les</span> trois tumeurs abdominales les plus fréquentes se partagent à parts égales (<span class=\"kw-chiffre\">≈ 30 %</span> chacune) : <span class=\"kw-etio\">neuroblastome</span>, <span class=\"kw-etio\">néphroblastome</span> et <span class=\"kw-etio\">lymphome B de haut grade</span> (Burkitt). Le siège oriente : <span class=\"kw-clinique\">rétropéritonéal</span> (néphroblastome rénal, neuroblastome extra-rénal), <span class=\"kw-clinique\">intrapéritonéal</span> (lymphome, hépatoblastome), <span class=\"kw-clinique\">pelvien</span> (tumeur ovarienne, tératome sacrococcygien).</p>\n      <p><strong>Circonstances de découverte</strong> :</p>\n      <table >\n        <thead><tr><th>Signe</th><th>Précisions / orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Masse / ↑ du volume abdominal</span></td><td>Surtout <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">tumeurs du blastème</span> ; souvent découverte fortuite au bain ou à l'examen</td></tr>\n          <tr><td><span class=\"kw-clinique\">HTA</span></td><td><span class=\"kw-etio\">Neuroblastome</span> (compression vasculo-rénale, amines vasopressives), <span class=\"kw-etio\">néphroblastome</span>, phéochromocytome</td></tr>\n          <tr><td><span class=\"kw-clinique\">Hématurie</span></td><td>Évoque un <span class=\"kw-etio\">néphroblastome</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">AEG</span></td><td>Témoigne souvent de <span class=\"kw-alerte\">métastases ostéomédullaires d'un neuroblastome</span></td></tr>\n          <tr><td>Signes endocriniens</td><td><strong>Hypercorticisme :</strong> corticosurrénalome ; <strong>puberté précoce / virilisation :</strong> tumeur des cordons sexuels</td></tr>\n          <tr><td>Syndromes paranéoplasiques du <span class=\"kw-etio\">neuroblastome</span></td><td><span class=\"kw-clinique\">Syndrome opso-myoclonique</span> (mouvements oculaires saccadés + ataxie) ; <span class=\"kw-clinique\">diarrhée</span> par hypersécrétion de <span class=\"kw-bio\">VIP</span> ; <span class=\"kw-clinique\">hématome péri-orbitaire</span> (sd de Hutchinson) ; nodules bleutés sous-cutanés du nourrisson</td></tr>\n          <tr><td>Malformation <span class=\"kw-etio\">congénitale</span></td><td><span class=\"kw-clinique\">Aniridie</span> et <span class=\"kw-clinique\">hémi-hypertrophie corporelle</span> → néphroblastome</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Tableaux aigus révélateurs.</strong> <span class=\"kw-alerte\">Invagination intestinale aiguë</span> après <span class=\"kw-chiffre\">5 ans</span> (lymphome de Burkitt) ; <span class=\"kw-alerte\">torsion d'annexe</span> (tumeur ovarienne) ; rétention aiguë d'urine ou signes médullaires (neuroblastome paravertébral « en sablier ») ; <span class=\"kw-alerte\">choc hypovolémique</span> par <span class=\"kw-alerte\">rupture</span> <span class=\"kw-etio\">tumorale</span>.</div>\n      <p><strong>Comparatif des trois grandes tumeurs abdominales</strong> :</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-etio\">Néphroblastome</span> (Wilms)</th><th><span class=\"kw-etio\">Neuroblastome</span></th><th><span class=\"kw-etio\">Lymphome</span></th></tr></thead>\n        <tbody>\n          <tr><td>Âge</td><td><span class=\"kw-chiffre\">&lt; 5 ans</span></td><td><span class=\"kw-chiffre\">&lt; 6 ans</span> (<span class=\"kw-chiffre\">40 %</span> &lt;<span class=\"kw-chiffre\"> 1 an</span>)</td><td>Garçon, <span class=\"kw-chiffre\">5-10 ans</span></td></tr>\n          <tr><td>Origine</td><td>Rein (bilatéralité possible)</td><td>Médullosurrénale, ganglions sympathiques (rétropéritonéal)</td><td>Péritoine (souvent extra-ganglionnaire)</td></tr>\n          <tr><td>Découverte</td><td><span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">hématurie</span></td><td><span class=\"kw-clinique\">HTA</span>, compression médullaire, métastases (orbite, peau, moelle, foie)</td><td><span class=\"kw-alerte\">Invagination intestinale aiguë</span></td></tr>\n          <tr><td>Prédisposition</td><td>Beckwith-Wiedemann, WAGR, Denys-Drash</td><td>—</td><td>Déficit immunitaire</td></tr>\n          <tr><td>Imagerie</td><td>Signe de l'éperon ; <strong>extension vasculaire</strong> (VCI/veine rénale) ; calcifications rares</td><td>Refoule le rein ; <strong>atteinte péri-vasculaire infiltrante</strong> ; <span class=\"kw-radio\">calcifications fréquentes</span> ; <span class=\"kw-ttt\">infiltration</span> du canal rachidien</td><td>Atteinte ganglionnaire massive et mésentérique ; <span class=\"kw-clinique\">ascite</span></td></tr>\n          <tr><td>Bilan spécifique</td><td><span class=\"kw-imagerie\">TDM pulmonaire</span> (métastases)</td><td><span class=\"kw-bio\">Catécholamines urinaires</span>, <span class=\"kw-imagerie\">scintigraphie MIBG</span>, myélogramme/<span class=\"kw-imagerie\">BOM</span>, <span class=\"kw-bio\">N-myc</span></td><td><span class=\"kw-bio\">LDH</span>, <span class=\"kw-imagerie\">TEP-TDM</span>, myélogramme, analyse du <span class=\"kw-bio\">LCS</span></td></tr>\n          <tr><td>Métastases</td><td>Poumon</td><td>Peau et foie (nourrisson), péri-orbitaire, moelle osseuse</td><td>SNC, moelle osseuse</td></tr>\n          <tr><td><span class=\"kw-def\">Pronostic</span></td><td>Survie <span class=\"kw-chiffre\">≈ 90 %</span> (<span class=\"kw-ttt\">chirurgie</span> + chimio ± <span class=\"kw-imagerie\">RT</span>)</td><td>Hétérogène : <span class=\"kw-chiffre\">&gt; 90 %</span> si localisé &lt;<span class=\"kw-chiffre\"> 18 mois</span> ; <span class=\"kw-chiffre\">&lt; 40 %</span> si N-myc amplifié</td><td>Survie <span class=\"kw-chiffre\">&gt; 90 %</span> (chimio seule, sans <span class=\"kw-ttt\">chirurgie</span>)</td></tr>\n        </tbody>\n      </table>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/neuroblastoma","label":"Radiopaedia : Neuroblastoma"},{"href":"https://radiopaedia.org/articles/wilms-tumour-3","label":"Radiopaedia : Wilms tumour (néphroblastome)"}]},{"id":"297-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur thoracique chez l’enfant","contenu":"<p>Une tumeur thoracique de l'enfant se révèle par des signes liés à la <span class=\"kw-clinique\">compression médiastinale</span> : manifestations <span class=\"kw-clinique\">respiratoires</span>, <span class=\"kw-clinique\">circulatoires</span>, <span class=\"kw-clinique\">neurologiques</span>, <span class=\"kw-clinique\">digestives</span> ou <span class=\"kw-clinique\">pariétales</span>.</p>\n      <table >\n        <thead><tr><th>Signe d'appel</th><th>Tumeur évoquée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Dyspnée</span> par compression médiastinale</td><td><span class=\"kw-etio\">Lymphome</span> (le plus souvent) ; plus rarement tumeur germinale maligne, sarcome, neuroblastome</td></tr>\n          <tr><td>Obstruction respiratoire haute, troubles de déglutition</td><td>Tumeur ORL (lymphome, rhabdomyosarcome)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-alerte\">dyspnée asphyxiante</span> peut révéler un <span class=\"kw-etio\">lymphome non hodgkinien médiastinal</span> (ou une tumeur ORL) — c'est une urgence diagnostique et thérapeutique (risque de compression trachéale et cave supérieure).</div>\n      <p><strong>Stratégie d'imagerie</strong> selon le compartiment médiastinal :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">RXT</span> ± <span class=\"kw-imagerie\">échographie</span> en 1ʳᵉ intention (opacité pulmonaire ou médiastinale)</li>\n        <li><span class=\"kw-imagerie\">TDM thoracique</span> pour le médiastin antérieur et moyen</li>\n        <li><span class=\"kw-imagerie\">IRM</span> pour le médiastin postérieur</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":0},{"id":"297-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur osseuse chez l’enfant","contenu":"<p><span class=\"kw-etio\">Ostéosarcome</span> et <span class=\"kw-etio\">sarcome d'Ewing</span> représentent <span class=\"kw-chiffre\">90 %</span> des sarcomes osseux de l'enfant et de l'adolescent. Ils prédominent chez l'<span class=\"kw-clinique\">adolescent</span> (sex-ratio <span class=\"kw-chiffre\">1,5 G / 1 F</span>). Le diagnostic est souvent retardé par l'évocation de causes bénignes (entorse, douleur post-traumatique).</p>\n      <div class=\"callout callout-warn\"><strong>Signe d'alerte = la douleur.</strong> Profonde, localisée sur un membre, durable mais d'intensité variable, <span class=\"kw-alerte\">lentement progressive puis d'allure inflammatoire</span> (réveillant la nuit). L'<span class=\"kw-clinique\">état général est le plus souvent conservé</span> (surtout dans l'ostéosarcome).</div>\n      <p>Autres manifestations : <span class=\"kw-clinique\">tuméfaction</span> en regard de l'os, <span class=\"kw-alerte\">fracture pathologique</span> inaugurale, inflammation locale avec <span class=\"kw-clinique\">fièvre</span> (piège : oriente à tort vers une infection osseuse).</p>\n      <p><strong>Comparatif ostéosarcome / sarcome d'Ewing</strong> :</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-etio\">Ostéosarcome</span></th><th><span class=\"kw-etio\">Sarcome d'Ewing</span></th></tr></thead>\n        <tbody>\n          <tr><td>Fréquence</td><td>Tumeur osseuse maligne la plus fréquente de l'enfant</td><td>Origine <span class=\"kw-def\">neuroectodermique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">AEG</span> / <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span></td><td><strong>Absents</strong></td><td><span class=\"kw-alerte\">AEG + syndrome inflammatoire précoce</span></td></tr>\n          <tr><td>Localisation</td><td>Os longs, <span class=\"kw-clinique\">métaphyse</span> ; « <span class=\"kw-clinique\">près du genou, loin du coude</span> »</td><td>Tous <span class=\"kw-clinique\">les</span> os ; os plats (bassin, vertèbre) et os longs (diaphyse/métaphyse)</td></tr>\n          <tr><td>Imagerie (RX)</td><td>Ostéolytique / ostéocondensant / mixte ; réaction périostée en <span class=\"kw-radio\">« feu d'herbe »</span> ; <span class=\"kw-radio\">éperon de Codman</span></td><td><span class=\"kw-clinique\">Lésion</span> ostéolytique ; réaction périostée en <span class=\"kw-radio\">« bulbe d'oignon »</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Histologie</span> / biologie</td><td>Matrice <span class=\"kw-bio\">ostéoïde</span> <span class=\"kw-etio\">tumorale</span> anormale</td><td>Tumeur à <span class=\"kw-bio\">petites cellules rondes</span> ; <span class=\"kw-bio\">translocation t(11;22)</span> (FISH/<span class=\"kw-bio\">PCR</span>)</td></tr>\n          <tr><td>Extension</td><td>Métastases pulmonaires</td><td><span class=\"kw-alerte\">Métastases pulmonaires précoces</span> ; <span class=\"kw-bio\">envahissement</span> médullaire (myélogramme + <span class=\"kw-imagerie\">BOM</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Particularité du sarcome d'Ewing.</strong> Une composante <span class=\"kw-clinique\">extra-osseuse</span> importante peut donner des signes aigus et trompeurs : <span class=\"kw-clinique\">compression radiculaire ou médullaire</span>, <span class=\"kw-clinique\">détresse respiratoire</span> par épanchement pleural. La <span class=\"kw-bio\">biopsie</span> (à l'état frais) confirme le diagnostic.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/osteosarcoma","label":"Radiopaedia : Osteosarcoma"},{"href":"https://radiopaedia.org/articles/ewing-sarcoma","label":"Radiopaedia : Ewing sarcoma"},{"href":"https://radiopaedia.org/articles/bone-tumors-overview","label":"Radiopaedia : Bone tumours (overview)"}]},{"id":"297-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et objectifs des examens d’imagerie devant une situation évocatrice de cancer de l’enfant (tumeurs cérébrale, abdominale, thoracique et osseuse)","contenu":"<p>Devant une situation évocatrice de cancer, le réflexe est le <strong><span class=\"kw-def\">contact</span> rapide avec un centre de référence en cancérologie pédiatrique</strong>. L'imagerie oriente le diagnostic et réalise le <span class=\"kw-def\">bilan d'extension</span> ; elle est choisie selon la localisation.</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Imagerie de choix</th></tr></thead>\n        <tbody>\n          <tr><td>Cérébrale (SNC)</td><td><span class=\"kw-imagerie\">IRM</span> cérébrale ou cérébro-spinale = examen de référence (topographie, dissémination, dilatation ventriculaire)</td></tr>\n          <tr><td>Abdominale</td><td><span class=\"kw-imagerie\">Échographie</span> = examen phare (siège, 1ᵉʳ <span class=\"kw-def\">bilan d'extension</span>) ; puis <span class=\"kw-imagerie\">TDM</span> et/ou <span class=\"kw-imagerie\">IRM</span> ; <span class=\"kw-imagerie\">TDM pulmonaire</span> systématique si néphroblastome</td></tr>\n          <tr><td>Thoracique</td><td><span class=\"kw-imagerie\">RXT</span> ± <span class=\"kw-imagerie\">échographie</span> ; <span class=\"kw-imagerie\">TDM thoracique</span> (médiastin ant/moyen) ; <span class=\"kw-imagerie\">IRM</span> (médiastin postérieur)</td></tr>\n          <tr><td>Osseuse</td><td><span class=\"kw-imagerie\">RX</span> en 1ʳᵉ intention ; <span class=\"kw-imagerie\">IRM</span> (bilan loco-régional, extension intra-osseuse) ; <span class=\"kw-imagerie\">TDM thoracique</span> (métastases pulmonaires)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Imageries spécifiques (médecine nucléaire)</strong> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Scintigraphie au Tc 99m</span> : tumeurs osseuses primitives et/ou métastatiques</li>\n        <li><span class=\"kw-imagerie\">Scintigraphie MIBG</span> : spécifique des tumeurs sympathiques (<span class=\"kw-etio\">neuroblastome</span>) et carcinoïdes</li>\n        <li><span class=\"kw-imagerie\">TEP-TDM (18-FDG)</span> : lymphome hodgkinien et non hodgkinien, sarcome</li>\n      </ul>\n      <p><strong>Marqueurs tumoraux</strong> — complètent l'imagerie :</p>\n      <table >\n        <thead><tr><th>Marqueur</th><th>Tumeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">α-fœtoprotéine (AFP)</span></td><td>Tumeurs germinales (sac vitellin), hépatoblastome</td></tr>\n          <tr><td><span class=\"kw-bio\">β-hCG</span></td><td>Tumeurs germinales (choriocarcinome)</td></tr>\n          <tr><td><span class=\"kw-bio\">Catécholamines urinaires</span> (<span class=\"kw-ttt\">dopamine</span>, HVA, VMA)</td><td><span class=\"kw-etio\">Neuroblastome</span></td></tr>\n          <tr><td><span class=\"kw-bio\">LDH</span> (agressivité)</td><td>LMNH, neuroblastome métastatique</td></tr>\n          <tr><td><span class=\"kw-bio\">Hypercalcémie</span></td><td>Atteintes étendues, tumeurs rhabdoïdes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Tumeurs ne nécessitant pas de preuve histologique.</strong> <span class=\"kw-etio\">Rétinoblastome</span> (<span class=\"kw-imagerie\">FO</span> caractéristique) ; <span class=\"kw-etio\">néphroblastome</span> (faisceau d'arguments clinico-radiologiques) ; certaines tumeurs infiltrantes du tronc cérébral (imagerie typique — mais souvent biopsiées pour analyse moléculaire). Sinon, la <span class=\"kw-bio\">biopsie</span> est transmise <strong>à l'état frais</strong> (congélation <span class=\"kw-etio\">tumorale</span> pour caractérisation génétique).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":4}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU &amp; Pièges » et « Stratégie &amp; CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> thérapeutique</strong></p><p>Démarche diagnostique menée <strong>en parallèle</strong> de la PEC urgente quand elle est nécessaire</p><ul><li>Toute tumeur pédiatrique est considérée comme une <span class=\"kw-alerte\">urgence thérapeutique</span></li><li>Croissance <span class=\"kw-etio\">tumorale</span> parfois <span class=\"kw-alerte\">extrêmement rapide</span> (quelques jours) — non synonyme de gravité, mais impose une orientation sans délai</li></ul><p><strong><span class=\"kw-alerte\">HTIC</span> / tumeur cérébrale</strong></p><p><span class=\"kw-imagerie\">Imagerie cérébrale en urgence</span> devant toute anomalie clinique</p><ul><li><span class=\"kw-ttt\">Transfert immédiat en neurochirurgie</span> : <span class=\"kw-ttt\">DVE</span> ou <span class=\"kw-ttt\">ventriculo-cisternostomie</span> (plutôt que dérivation ventriculo-péritonéale)</li><li><span class=\"kw-ttt\">Corticothérapie</span> ± <span class=\"kw-ttt\">perfusions IV de mannitol</span></li></ul><p><strong><span class=\"kw-clinique\">Dyspnée</span> asphyxiante</strong></p><p><span class=\"kw-alerte\">Urgence</span> <strong>diagnostique et thérapeutique</strong> (risque de compression trachéale et cave supérieure)</p><ul><li>Révèle un <span class=\"kw-def\">lymphome non hodgkinien médiastinal</span> ou une <span class=\"kw-def\">tumeur ORL</span></li></ul>","hospit":"<p><strong>Centre de référence :</strong> <span class=\"kw-def\">contact</span> rapide ; PEC uniquement au sein des <span class=\"kw-def\">centres spécialisés en cancérologie pédiatrique</span>.<br><strong>Tumeur cérébrale :</strong> PEC <span class=\"kw-ttt\">neuro-oncologique spécialisée pluridisciplinaire</span> ; transfert en neurochirurgie si <span class=\"kw-alerte\">HTIC</span>.<br><strong><span class=\"kw-ttt\">Radiothérapie</span> :</strong> chez l'enfant de <span class=\"kw-chiffre\">&lt; 16 ans</span>, réalisée en centres spécialisés (effets secondaires importants).<br><strong>Médecin traitant :</strong> informé en temps réel dès le 1ᵉʳ temps hospitalier, interlocuteur privilégié associé au parcours de soins.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Dyspnée asphyxiante</span> → <span class=\"kw-def\">lymphome non hodgkinien médiastinal</span> ou <span class=\"kw-def\">tumeur ORL</span></li><li><span class=\"kw-alerte\">Pancytopénie</span> (<span class=\"kw-clinique\">anémie aiguë</span>, <span class=\"kw-clinique\">saignement</span>, <span class=\"kw-clinique\">fièvre</span>) ± <span class=\"kw-alerte\">CIVD</span> → <span class=\"kw-def\">hémopathie</span></li><li><span class=\"kw-alerte\">HTIC d'évolution rapide</span> avec <span class=\"kw-clinique\">signes neurovégétatifs</span> et <span class=\"kw-clinique\">convulsions</span> → <span class=\"kw-def\">tumeur cérébrale</span></li><li><span class=\"kw-alerte\">Fracture osseuse pathologique</span> → <span class=\"kw-def\">tumeur osseuse</span></li><li><span class=\"kw-alerte\">Hémorragie intra-abdominale</span> par <span class=\"kw-alerte\">rupture</span> <span class=\"kw-etio\">tumorale</span> → <span class=\"kw-def\">néphroblastome</span></li><li><span class=\"kw-alerte\">Hypercalcémie</span> → origine <span class=\"kw-etio\">paranéoplasique</span> ou <span class=\"kw-etio\">lyse osseuse</span></li><li><span class=\"kw-alerte\">AEG</span> témoignant souvent de <span class=\"kw-alerte\">métastases ostéomédullaires d'un neuroblastome</span></li><li><span class=\"kw-clinique\">Douleur osseuse</span> profonde, <span class=\"kw-alerte\">lentement progressive puis d'allure inflammatoire</span> (réveil nocturne) → <span class=\"kw-def\">sarcome osseux</span> (état général souvent conservé = piège)</li></ul>","principes":"<p>Tumeurs de l'enfant <span class=\"kw-alerte\">globalement chimiosensibles</span> (prolifération rapide) : le <span class=\"kw-def\">pronostic</span> (guérison <span class=\"kw-chiffre\">≈ 80 %</span>) repose sur une PEC <strong>pluridisciplinaire</strong> en centre spécialisé, l'inclusion dans des essais et l'association des modalités thérapeutiques.</p><p><strong><span class=\"kw-ttt\">Chimiothérapie</span></strong></p><ul><li>Particulièrement efficace sur <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">tumeurs embryonnaires</span> (grande <span class=\"kw-bio\">chimiosensibilité</span>)</li><li><span class=\"kw-ttt\">Polychimiothérapie néo-adjuvante</span> puis post-opératoire ; le <span class=\"kw-chiffre\">% de cellules tumorales viables</span> sur la pièce = facteur pronostique orientant la chimio post-op</li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span></strong></p><ul><li><span class=\"kw-ttt\">Exérèse monobloc extratumorale</span></li><li><span class=\"kw-ttt\">Biopsie</span> transmise <strong>à l'état frais</strong> (congélation <span class=\"kw-etio\">tumorale</span> pour analyses moléculaires), réalisée par le chirurgien qui assurera l'<span class=\"kw-ttt\">exérèse</span></li></ul><p><strong><span class=\"kw-ttt\">Radiothérapie</span></strong></p><ul><li>Chez l'enfant <span class=\"kw-chiffre\">&lt; 16 ans</span> : uniquement en <span class=\"kw-def\">centre spécialisé</span> (effets secondaires importants)</li><li>Adjuvante dans le <span class=\"kw-def\">sarcome d'Ewing</span> uniquement</li></ul><p><strong>Aménagements si prédisposition <span class=\"kw-etio\">génétique</span></strong></p><p><span class=\"kw-ci\">Non-recours à la radiothérapie ou à certaines chimiothérapies</span> ; adaptation des doses et de la <span class=\"kw-def\">surveillance</span></p><ul><li>Certains syndromes (ex. <span class=\"kw-etio\">Li-Fraumeni</span>) exposent à une <span class=\"kw-alerte\">toxicité majeure des traitements</span></li></ul>","suivi":"<p><strong>Dispositif d'<span class=\"kw-def\">annonce</span></strong> (Plan cancer) en <span class=\"kw-chiffre\">4 temps</span> (médical, accompagnement soignant, soins de support, articulation avec la médecine de ville) ; s'applique aussi aux <span class=\"kw-alerte\">rechutes</span>.<br><strong><span class=\"kw-def\">PPS</span></strong> = <span class=\"kw-def\">Programme personnalisé de soins</span>, pierre angulaire : document écrit décrivant le traitement validé en <span class=\"kw-def\">RCP</span> et le calendrier prévisionnel de soins et de <span class=\"kw-def\">suivi</span>.<br><strong>Enquête <span class=\"kw-etio\">génétique</span> familiale :</strong> <span class=\"kw-def\">surveillance</span> des enfants porteurs de l'anomalie, voire diagnostic prénatal pour <span class=\"kw-clinique\">les</span> grossesses à venir.<br><strong>Phase palliative :</strong> concerne <span class=\"kw-chiffre\">20 %</span> des enfants atteints de cancer.</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/hematologie-cancerologie/cancers","label":"Pédia-Univ — référentiel cancers de l’enfant"}],"cards":[{"i":"148d3ba676a4","n":297,"o":"297-3","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur cérébrale chez l’enfant","q":"Quel est le signe d'appel le plus fréquent d'une tumeur cérébrale chez l'enfant ?","a":"<p>Le signe d'appel le plus fréquent d'une tumeur cérébrale chez l'enfant est le <strong>syndrome d'hypertension intracrânienne (HTIC)</strong>.</p>"},{"i":"1e92833d534c","n":297,"o":"297-3","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur cérébrale chez l’enfant","q":"Quelle est la fréquence des tumeurs cérébrales chez l'enfant et leur place dans les cancers pédiatriques ?","a":"<p>Les tumeurs cérébrales représentent la <strong>deuxième cause de cancer chez l'enfant</strong>, comptant pour environ <strong>25%</strong> des cancers pédiatriques.</p>"},{"i":"27270f4ef53f","n":297,"o":"297-3","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur cérébrale chez l’enfant","q":"Quelles sont les caractéristiques des vomissements associés à une hypertension intracrânienne (HTIC) chez l'enfant ?","a":"<p>Les vomissements associés à une HTIC sont :</p><ul><li><strong>Inconstants</strong>.</li><li>Souvent <strong>en jet</strong> (sans nausée préalable).</li><li>Typiquement <strong>matinaux</strong>.</li><li>Ils peuvent parfois <strong>soulager transitoirement les céphalées</strong>.</li></ul>"},{"i":"5f2c246cddca","n":297,"o":"297-3","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur cérébrale chez l’enfant","q":"Quelles sont les caractéristiques des céphalées suggestives d'une hypertension intracrânienne (HTIC) chez l'enfant ?","a":"<p>Les céphalées suggestives d'une HTIC sont :</p><ul><li>Des céphalées <strong>récentes, inhabituelles, durables</strong> et <strong>s'aggravant</strong>.</li><li>Souvent matinales (au réveil) ou en deuxième moitié de nuit.</li><li><strong>Exagérées par la toux, l'effort, le décubitus</strong>.</li><li><strong>Rebelles aux antalgiques</strong> habituels.</li></ul>"},{"i":"aa27c0a37172","n":297,"o":"297-3","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur cérébrale chez l’enfant","q":"Quelle est la prise en charge initiale en cas de suspicion d'HTIC chez l'enfant ?","a":"<p>En cas de suspicion d'HTIC chez l'enfant, la prise en charge initiale est une <strong>urgence</strong> :</p><ul><li><strong>Transfert immédiat en neurochirurgie</strong>.</li><li>Mise en place d'une intervention pour la dérivation du liquide cérébrospinal (<strong>DVE / ventriculocisternostomie</strong>).</li><li>Administration d'une <strong>corticothérapie</strong>.</li><li>Éventuellement, administration de <strong>mannitol IV</strong>.</li></ul>"},{"i":"b37304361e3b","n":297,"o":"297-3","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur cérébrale chez l’enfant","q":"Outre l'HTIC, quels autres signes cliniques peuvent évoquer une tumeur cérébrale chez l'enfant ?","a":"<p>D'autres signes cliniques pouvant évoquer une tumeur cérébrale chez l'enfant, parfois même sans HTIC, incluent :</p><ul><li>Une <strong>comitialité</strong>, souvent à type de crises partielles.</li><li>Un <strong>déficit visuel</strong>.</li><li>Tout <strong>signe de localisation neurologique</strong> (atteinte motrice, atteinte des paires crâniennes, syndrome cérébelleux).</li><li>Un <strong>déficit endocrinien d'origine centrale</strong>.</li></ul>"},{"i":"0942768db09f","n":297,"o":"297-4","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur abdominale chez l’enfant","q":"Quels sont les signes cliniques évocateurs d'une tumeur abdominale chez l'enfant au-delà de la masse abdominale ?","a":"<ul><li><strong>Hypertension artérielle (HTA)</strong> : peut orienter vers un <strong>neuroblastome</strong> (compression vasculo-rénale, amines vasopressives) ou un <strong>néphroblastome</strong>.</li><li><strong>Hématurie</strong> : très évocatrice d'un <strong>néphroblastome</strong>.</li><li><strong>Altération de l'état général (AEG)</strong> : suggère des métastases ostéomédullaires, notamment du <strong>neuroblastome</strong>.</li><li><strong>Signes endocriniens</strong> : un <strong>hypercorticisme</strong> peut orienter vers un corticosurrénalome ; une puberté précoce ou virilisation vers une tumeur des cordons sexuels.</li><li><strong>Syndromes paranéoplasiques du neuroblastome</strong> : <strong>syndrome opso-myoclonique</strong> (mouvements oculaires saccadés + ataxie), <strong>diarrhée</strong> par hypersécrétion de VIP, <strong>hématome péri-orbitaire</strong> (syndrome de Hutchinson), <strong>nodules bleutés sous-cutanés</strong> chez le nourrisson.</li><li><strong>Malformations congénitales associées</strong> : <strong>aniridie</strong> et <strong>hémi-hypertrophie corporelle</strong> orientent vers un <strong>néphroblastome</strong>.</li><li><strong>Tableaux aigus révélateurs</strong> : <strong>invagination intestinale aiguë après 5 ans</strong> (lymphome de Burkitt), <strong>torsion d'annexe</strong> (tumeur ovarienne), <strong>rétention aiguë d'urine ou signes médullaires</strong> (neuroblastome paravertébral « en sablier »), ou <strong>choc hypovolémique</strong> par rupture tumorale.</li></ul>"},{"i":"4802669e9958","n":297,"o":"297-4","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur abdominale chez l’enfant","q":"Quelles sont les trois tumeurs abdominales les plus fréquentes à évoquer chez l'enfant et leur part respective ?","a":"<p>Les trois tumeurs abdominales les plus fréquentes chez l'enfant sont le <strong>neuroblastome</strong>, le <strong>néphroblastome</strong> (tumeur de Wilms) et le <strong>lymphome B de haut grade (Burkitt)</strong>, chacune représentant environ <strong>30 %</strong> des cas.</p>"},{"i":"5962e6d9c4f2","n":297,"o":"297-4","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur abdominale chez l’enfant","q":"Comment l'âge de l'enfant peut-il orienter vers les principales tumeurs abdominales ?","a":"<ul><li><strong>Néphroblastome (Wilms)</strong> : survient généralement <strong>avant 5 ans</strong>.</li><li><strong>Neuroblastome</strong> : survient majoritairement <strong>avant 6 ans</strong>, dont 40 % des cas <strong>avant 1 an</strong>.</li><li><strong>Lymphome de Burkitt</strong> : touche plus souvent les garçons de <strong>5 à 10 ans</strong>.</li></ul>"},{"i":"2d9332eeb4f5","n":297,"o":"297-5","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur thoracique chez l’enfant","q":"Quels sont les différents types de manifestations cliniques devant faire évoquer une tumeur thoracique chez l'enfant ?","a":"<p>Une tumeur thoracique chez l'enfant peut se manifester par des signes liés à une <strong>compression médiastinale</strong>, affectant divers systèmes :</p><ul><li>Manifestations <strong>respiratoires</strong></li><li>Manifestations <strong>circulatoires</strong></li><li>Manifestations <strong>neurologiques</strong></li><li>Manifestations <strong>digestives</strong></li><li>Manifestations <strong>pariétales</strong></li></ul>"},{"i":"81ee64712419","n":297,"o":"297-5","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur thoracique chez l’enfant","q":"Pourquoi une dyspnée asphyxiante chez l'enfant, révélant un lymphome non hodgkinien médiastinal, constitue-t-elle une urgence ?","a":"<p>Une dyspnée asphyxiante, révélant un lymphome non hodgkinien médiastinal (ou une tumeur ORL), constitue une <strong>urgence diagnostique et thérapeutique</strong> du fait du <strong>risque de compression trachéale et de veine cave supérieure</strong>, pouvant engager le pronostic vital.</p>"},{"i":"f6ad42d8efe3","n":297,"o":"297-5","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur thoracique chez l’enfant","q":"Quelle est la cause la plus fréquente d'une dyspnée par compression médiastinale chez l'enfant et quelles autres étiologies doivent être évoquées ?","a":"<p>La cause la plus fréquente d'une dyspnée par compression médiastinale chez l'enfant est un <strong>lymphome</strong>. Plus rarement, il faut évoquer une <strong>tumeur germinale maligne</strong>, un <strong>sarcome</strong> ou un <strong>neuroblastome</strong>.</p>"},{"i":"5799ab899824","n":297,"o":"297-6","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur osseuse chez l’enfant","q":"Quel est le principal signe d'alerte devant faire évoquer une tumeur osseuse chez l'enfant, et quelles sont ses caractéristiques typiques ?","a":"<p>Le principal signe d'alerte est la <strong>douleur</strong>. Ses caractéristiques sont :</p><ul><li>Profonde</li><li>Localisée sur un membre</li><li>Durable mais d'intensité variable</li><li>Lentement progressive</li><li>D'allure inflammatoire (réveille la nuit)</li></ul>"},{"i":"780977f08834","n":297,"o":"297-6","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur osseuse chez l’enfant","q":"Quelles sont les autres manifestations cliniques des tumeurs osseuses chez l'enfant, en dehors de la douleur ?","a":"<p>Les autres manifestations cliniques sont :</p><ul><li>Une <strong>tuméfaction</strong> palpable en regard de l'os.</li><li>Une <strong>fracture pathologique</strong> inaugurale, survenant sur un os fragilisé.</li><li>Une <strong>inflammation locale avec fièvre</strong>, pouvant orienter à tort vers une infection osseuse.</li><li>L'<strong>état général est le plus souvent conservé</strong>, surtout dans l'ostéosarcome.</li></ul>"},{"i":"bc4ed23f773e","n":297,"o":"297-6","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur osseuse chez l’enfant","q":"Quelles sont les particularités cliniques pouvant orienter vers un sarcome d'Ewing par rapport à un ostéosarcome chez l'enfant ?","a":"<p>Certaines particularités cliniques orientent vers le sarcome d'Ewing :</p><ul><li>Présence précoce d'un <strong>altération de l'état général (AEG)</strong> et d'un <strong>syndrome inflammatoire</strong>, contrairement à l'ostéosarcome où ils sont généralement absents.</li><li>Une composante <strong>extra-osseuse importante</strong> peut entraîner des signes aigus et trompeurs tels qu'une compression radiculaire ou médullaire, ou une détresse respiratoire par épanchement pleural.</li></ul>"},{"i":"f603866cae80","n":297,"o":"297-6","u":"Diagnostic positif","t":"Connaître les circonstances et signes cliniques devant faire évoquer une tumeur osseuse chez l’enfant","q":"Quelle est la part des ostéosarcomes et des sarcomes d'Ewing dans les tumeurs osseuses malignes de l'enfant et de l'adolescent, et quelle est leur démographie typique ?","a":"<p>Les ostéosarcomes et les sarcomes d'Ewing représentent <strong>90 %</strong> des sarcomes osseux chez l'enfant et l'adolescent. Ils prédominent spécifiquement chez l'adolescent, avec un sex-ratio de <strong>1,5 garçon pour 1 fille</strong>.</p>"}]};